public class InnerExperimentTemplateExperimentTemplateExperimentReportConfigurationFactory(Action<Humidifier.FIS.ExperimentTemplateTypes.ExperimentTemplateExperimentReportConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.FIS.ExperimentTemplateTypes.ExperimentTemplateExperimentReportConfiguration>
{

    internal InnerExperimentTemplateDataSourcesFactory DataSourcesFactory { get; set; }

    internal InnerExperimentTemplateOutputsFactory OutputsFactory { get; set; }

    protected override Humidifier.FIS.ExperimentTemplateTypes.ExperimentTemplateExperimentReportConfiguration Create()
    {
        var experimentTemplateExperimentReportConfigurationResult = CreateExperimentTemplateExperimentReportConfiguration();
        factoryAction?.Invoke(experimentTemplateExperimentReportConfigurationResult);

        return experimentTemplateExperimentReportConfigurationResult;
    }

    private Humidifier.FIS.ExperimentTemplateTypes.ExperimentTemplateExperimentReportConfiguration CreateExperimentTemplateExperimentReportConfiguration()
    {
        var experimentTemplateExperimentReportConfigurationResult = new Humidifier.FIS.ExperimentTemplateTypes.ExperimentTemplateExperimentReportConfiguration();

        return experimentTemplateExperimentReportConfigurationResult;
    }
    public override void CreateChildren(Humidifier.FIS.ExperimentTemplateTypes.ExperimentTemplateExperimentReportConfiguration result)
    {
        base.CreateChildren(result);

        result.DataSources ??= DataSourcesFactory?.Build();
        result.Outputs ??= OutputsFactory?.Build();
    }

} // End Of Class

